import {PLANT_DAYS,PLANT_CONDITIONS,PLANT_SPECIMENS,PLANT_MODEL,plantObservation,plantObservationById,plantQuestionById} from './plant-study-content.mjs';
const PAGES=['predict','observe','compare','plan'],PREDICTIONS=['light','dim','similar','unsure'],LOCATIONS=['light','dim','unsure'],SUPPORT=['help','example','audio','together'];
const object=x=>x!==null&&typeof x==='object'&&!Array.isArray(x);
const clone=x=>JSON.parse(JSON.stringify(x));
const keys=(x,required,optional=[])=>object(x)&&required.every(k=>Object.hasOwn(x,k))&&Object.keys(x).every(k=>required.includes(k)||optional.includes(k));
const uniqueDays=x=>Array.isArray(x)&&x.length<=4&&new Set(x).size===x.length&&x.every(d=>PLANT_DAYS.includes(d));
const supportValid=s=>object(s)&&Object.entries(s).every(([k,v])=>SUPPORT.includes(k)&&v===true);
const supportMerge=(...ss)=>Object.assign({},...ss);
const predictionValid=p=>p===null||keys(p,['choice','timing','shownDays','support'])&&supportValid(p.support)&&PREDICTIONS.includes(p.choice)&&uniqueDays(p.shownDays)&&p.timing===(p.shownDays.some(d=>d>0)?'after-later-days':'before-later-days');
function recordValid(id,r){const q=plantQuestionById(id);return q&&keys(r,['attempts','support'])&&supportValid(r.support)&&Array.isArray(r.attempts)&&r.attempts.length<=24&&r.attempts.every(a=>keys(a,['choice','support','practice','familiar'])&&q.choices.some(c=>c.id===a.choice)&&supportValid(a.support)&&a.practice===true&&typeof a.familiar==='boolean');}
const sourceSupportValid=s=>keys(s,['global','questions'])&&supportValid(s.global)&&object(s.questions)&&Object.entries(s.questions).every(([id,v])=>plantQuestionById(id)&&supportValid(v));
// The carried copy stays frozen; later content corrections must not make it unreadable.
function observationValid(o){return object(o)&&!!plantObservationById(o.id);}
function planValid(p){return p===null||keys(p,['location','observation','sourceSupport','notice'])&&LOCATIONS.includes(p.location)&&observationValid(p.observation)&&sourceSupportValid(p.sourceSupport)&&typeof p.notice==='string';}
function valid(r){return keys(r,['version','page','day','condition','specimen','shownDays','prediction','observations','questions','support','location','plan'],['recovered'])&&r.version===1&&PAGES.includes(r.page)&&PLANT_DAYS.includes(r.day)&&PLANT_CONDITIONS.some(c=>c.id===r.condition)&&PLANT_SPECIMENS.includes(r.specimen)&&uniqueDays(r.shownDays)&&keys(r.prediction,['first','latest'])&&predictionValid(r.prediction.first)&&predictionValid(r.prediction.latest)&&((r.prediction.first===null)===(r.prediction.latest===null))&&Array.isArray(r.observations)&&r.observations.length<=16&&new Set(r.observations).size===r.observations.length&&r.observations.every(id=>plantObservationById(id))&&object(r.questions)&&Object.entries(r.questions).every(([id,v])=>recordValid(id,v))&&supportValid(r.support)&&(r.location===null||LOCATIONS.includes(r.location))&&planValid(r.plan);}
const fresh=()=>({version:1,page:'predict',day:0,condition:'light',specimen:'A',shownDays:[],prediction:{first:null,latest:null},observations:[],questions:{},support:{},location:null,plan:null});
// Looking at state never writes a learner response, exposure or default root.
export function plantStudy(state){return state.plantStudy===undefined?fresh():valid(state.plantStudy)?state.plantStudy:null;}
export function ensurePlantStudy(state){if(state.plantStudy===undefined)state.plantStudy=fresh();return plantStudy(state);}
export function recoverPlantStudy(state){if(state.plantStudy===undefined||plantStudy(state))return false;const original=state.plantStudy;state.plantStudy={...fresh(),recovered:original};return true;}
function change(state,fn){const current=plantStudy(state);if(!current)return false;const next=clone(current),result=fn(next);if(result===false||!valid(next))return false;state.plantStudy=next;return result??true;}
export function currentPlantObservation(state){const r=plantStudy(state);return r?plantObservation(r.day,r.condition,r.specimen):null;}
export function setPlantPage(state,page){if(!PAGES.includes(page))return false;return change(state,r=>{r.page=page;});}
export function setPlantDay(state,day){if(!PLANT_DAYS.includes(day))return false;return change(state,r=>{r.day=day;if(!r.shownDays.includes(day))r.shownDays.push(day);});}
export function setPlantSpecimen(state,condition,specimen){if(!PLANT_CONDITIONS.some(c=>c.id===condition)||!PLANT_SPECIMENS.includes(specimen))return false;return change(state,r=>{r.condition=condition;r.specimen=specimen;});}
export function recordPlantObservation(state){return change(state,r=>{if(!r.shownDays.includes(r.day))r.shownDays.push(r.day);const id=plantObservation(r.day,r.condition,r.specimen).id;if(!r.observations.includes(id))r.observations.push(id);return plantObservationById(id);});}
export function setPlantPrediction(state,choice){if(!PREDICTIONS.includes(choice))return false;return change(state,r=>{const prediction={choice,timing:r.shownDays.some(d=>d>0)?'after-later-days':'before-later-days',shownDays:[...r.shownDays],support:clone(r.support)};if(r.prediction.first===null)r.prediction.first=clone(prediction);r.prediction.latest=prediction;});}
export function usePlantSupport(state,kind,questionId=null){if(!SUPPORT.includes(kind)||questionId!==null&&!plantQuestionById(questionId))return false;return change(state,r=>{if(questionId===null)r.support[kind]=true;else{r.questions[questionId]??={attempts:[],support:{}};r.questions[questionId].support[kind]=true;}});}
export function answerPlantQuestion(state,id,choice){const q=plantQuestionById(id);if(!q||!q.choices.some(c=>c.id===choice))return false;return change(state,r=>{if(q.day!==null&&q.day!==r.day)return false;if(q.day!==null&&!r.shownDays.includes(q.day))r.shownDays.push(q.day);r.questions[id]??={attempts:[],support:{}};const record=r.questions[id],support=supportMerge(r.support,record.support);record.attempts.push({choice,support:clone(support),practice:true,familiar:record.attempts.length>0});record.attempts=record.attempts.slice(-24);return {correct:choice===q.answer,feedback:q.feedback[choice]};});}
export function choosePlantLocation(state,location){if(!LOCATIONS.includes(location))return false;return change(state,r=>{r.location=location;});}
export function carryPlantPlan(state,observationId){const observation=plantObservationById(observationId);if(!observation)return false;return change(state,r=>{if(r.location===null||!r.observations.includes(observationId))return false;r.plan={location:r.location,observation:clone(observation),sourceSupport:{global:clone(r.support),questions:Object.fromEntries(Object.entries(r.questions).map(([id,v])=>[id,clone(supportMerge(v.support,...v.attempts.map(a=>a.support)))]))},notice:PLANT_MODEL.notice};return clone(r.plan);});}
